  // DEV-HOUR: 5 * 9500 = 47500, VAT = 9975
  // PRINT-A4: 10 * 200 = 2000, VAT = 180
  // subtotal = 49500, vat = 10155, total = 59655
  assert.match(text, /Subtotal: €495\.00/);
  assert.match(text, /VAT: €101\.55/);
  assert.match(text, /Total: €596\.55/);
});

