test('createInvoice calculates correct total with tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // 10 * 9500 = 95000 subtotal
  // 95000 * 5 / 100 = 4750 discount
  // 95000 - 4750 = 90250 total
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.total, 90250);
});

test('addLine applies tier discount when not provided', () => {
  const r1 = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3 }); // No discountPercent
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 2.5); // Silver tier discount

